# region: sift
def sift(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs, factor=2):
    return [v * factor for v in xs]

# region: render
def render(xs, factor=2):
    return [v * factor for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(fold(render(digest(sift(raw)))))

